import {SPECTATOR_META} from './spectator-meta.js';
import {NARUTO_V2_META} from './naruto-v2-meta.js';
import {cinematicSteps} from '../engine/ultimate-rules.js';
export const COMIC_FONT='"Times New Roman", Times, serif';
export const COMIC_LINES={fullgetsuga:'This is everything I’ve got!',arise:'Arise.',supreme:'Kamehameha!',excalibur:'Excalibur!',cataclysm:'Know your place.',judgment:'Know your place before your empress.',void:'Domain Expansion: Unlimited Void.',shrine:'Domain Expansion: Malevolent Shrine.',purgatory:'Flame Breathing: Purgatory!',kuramarasengan:'Kurama! Giant Rasengan!',finalimpact:'This is the end!',narutotransform:'Baryon Mode!',meteor:'Tengai Shinsei!',fullforce:'Full Force Kamehameha!'};
function measured(ctx,text,size){const width=ctx.measureText?.(text)?.width;return Number.isFinite(width)?width:String(text).length*size*.5;}
export function comicLines(ctx,text,width,size=30){const lines=[];let line='';for(const word of String(text).trim().split(/\s+/)){const next=line?line+' '+word:word;if(measured(ctx,next,size)<=width){line=next;continue;}if(line){lines.push(line);line='';}for(const char of word){if(line&&measured(ctx,line+char,size)>width){lines.push(line);line='';}line+=char;}}if(line)lines.push(line);return lines;}
// Keep source cells intact: position the entire native frame using its opaque bounds.
export function drawComicSpeaker(ctx,images,f,progress,reduced=false){const baryon=f.id==='naruto_v2'&&f.baryon,key=f.id==='gojo'?'gojo_v2':baryon?'naruto_v2_baryon':f.id,m=SPECTATOR_META[f.id],im=images[key];if(!m||!im?.complete||!im.naturalWidth)return false;const meta=baryon?NARUTO_V2_META[key]:null,n=Math.min(m.bounds.length-1,Math.floor(progress*8)%m.bounds.length),bounds=meta?meta.bounds[0][Math.min(n,meta.rowCounts[0]-1)]:m.bounds[n],[w,h]=meta?.frameSize||m.frameSize;
 const scale=Math.min(190/(bounds[2]-bounds[0]),205/(bounds[3]-bounds[1])),slide=reduced?0:Math.max(0,1-progress*10)*20;
 ctx.save();ctx.translate(205-slide,524);ctx.scale(scale,scale);ctx.drawImage(im,n*w,0,w,h,-(bounds[0]+bounds[2])/2,-bounds[3],w,h);ctx.restore();return true;}
function bubble(ctx,x,y,w,h){const r=24;ctx.beginPath();ctx.moveTo(x+r,y);ctx.lineTo(x+w-r,y);ctx.quadraticCurveTo(x+w,y,x+w,y+r);ctx.lineTo(x+w,y+h-r);ctx.quadraticCurveTo(x+w,y+h,x+w-r,y+h);ctx.lineTo(x+r,y+h);ctx.quadraticCurveTo(x,y+h,x,y+h-r);ctx.lineTo(x,y+h*.46);ctx.lineTo(x-38,y+24);ctx.lineTo(x,y+h*.23);ctx.lineTo(x,y+r);ctx.quadraticCurveTo(x,y,x+r,y);ctx.closePath();ctx.fill();ctx.stroke();}
export function drawComicSpeech(ctx,images,f,c,name,line,reduced=false){const p=Math.max(0,Math.min(1,c.elapsed/cinematicSteps(c)));ctx.save();ctx.globalAlpha=Math.max(0,Math.min(1,p*10,(1-p)*12));drawComicSpeaker(ctx,images,f,p,reduced);
 const x=322,y=351,w=560,h=159;ctx.fillStyle='#fffdf7';ctx.strokeStyle='#101018';ctx.lineWidth=3;ctx.lineJoin='round';ctx.shadowColor='#0006';ctx.shadowBlur=reduced?0:8;ctx.shadowOffsetY=3;bubble(ctx,x,y,w,h);ctx.shadowColor='transparent';ctx.shadowBlur=0;ctx.shadowOffsetY=0;
 ctx.fillStyle='#34343e';ctx.textAlign='left';ctx.textBaseline='alphabetic';ctx.font=`bold 18px ${COMIC_FONT}`;ctx.fillText(name,x+26,y+29,w-52);
 let size=32,lines;do{ctx.font=`bold ${size}px ${COMIC_FONT}`;lines=comicLines(ctx,line,w-52,size);if(lines.length<=3||size<=24)break;size-=2;}while(true);
 ctx.fillStyle='#111116';ctx.textAlign='center';const lineHeight=size*1.12,top=y+54+(h-69-lines.length*lineHeight)/2+size*.85;
 for(const [i,t] of lines.slice(0,3).entries())ctx.fillText(t,x+w/2,top+i*lineHeight,w-52);ctx.restore();}
export function drawComicDialogue(ctx,images,d,names={},reduced=false){const c=d.narutoV2Transform||d.personalUltimate?.cinematic||d.teamUltimate?.cinematic;if(!c)return false;const f=d.fighters.find(f=>f.uid===(c.ownerUid??c.leaderUid));if(!f)return false;const name=names[f.id]||f.id.replaceAll('_',' ').toUpperCase(),line=c.style?.line||COMIC_LINES[c.kind]||'Let’s finish this!';drawComicSpeech(ctx,images,c.kind==='narutotransform'?{...f,baryon:true}:f,c,name,line,reduced);return true;}
